1: /* ==========================================================================
2:    Phase E5 Storm Atlas (ax): the population panel and its strip plot.
3: 
4:    Band hue never arrives as a literal in this file. Every element that
5:    colors itself carries a data-band attribute read straight from the
6:    verdict vocabulary, and the five mapping rules below resolve it
7:    against the --cp-band tokens in src/index.css, so the atlas, the
8:    console badge, and the forecast strip stay one palette with one
9:    source of truth.
10: 
11:    Nothing here animates. The field re-counts itself on every twist,
12:    and a population that changes must not also move on its own; the
13:    only motion this phase owns is the scroll into the console, which
14:    steps instead of glides under prefers-reduced-motion.
15:    ========================================================================== */
16: 
17: .ax-shell {
18:   display: grid;
19:   gap: var(--rp-s4);
20:   background: var(--cp-surface);
21:   border: 1px solid var(--cp-rule);
22:   border-radius: var(--cp-radius);
23:   padding: var(--rp-s5);
24:   min-width: 0;
25: }
26: 
27: /* Headline panel ---------------------------------------------------------- */
28: 
29: .ax-atlas {
30:   display: flex;
31:   flex-direction: column;
32:   gap: var(--rp-s3);
33:   min-width: 0;
34: }
35: 
36: .ax-headline {
37:   margin: 0;
38:   font-family: var(--rp-font-display);
39:   font-weight: 700;
40:   font-size: clamp(1.625rem, 3.4vw, 2.375rem);
41:   line-height: 1.2;
42:   color: var(--cp-ink);
43:   overflow-wrap: anywhere;
44: }
45: 
46: .ax-subline {
47:   display: flex;
48:   flex-wrap: wrap;
49:   align-items: baseline;
50:   gap: var(--rp-s2) var(--rp-s4);
51:   margin: 0;
52:   font-family: var(--rp-font-utility);
53:   font-size: 0.8125rem;
54:   font-variant-numeric: tabular-nums;
55:   color: var(--cp-ink-dim);
56: }
57: 
58: .ax-subline__count {
59:   color: var(--cp-ink);
60:   font-weight: 600;
61: }
62: 
63: .ax-compare {
64:   color: var(--rp-verified);
65: }
66: 
67: .ax-track {
68:   padding: 2px var(--rp-s3);
69:   border: 1px solid var(--cp-rule);
70:   border-radius: 999px;
71:   color: var(--cp-ink-faint);
72: }
73: 
74: /* Band cells: glyph, label, count, percent, all on one hue --------------- */
75: 
76: .ax-cells {
77:   display: grid;
78:   grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr));
79:   gap: var(--rp-s2);
80:   list-style: none;
81:   margin: 0;
82:   padding: 0;
83: }
84: 
85: .ax-cell {
86:   --ax-band: var(--cp-ink-faint);
87:   display: grid;
88:   grid-template-columns: auto minmax(0, 1fr);
89:   gap: 2px var(--rp-s2);
90:   align-content: start;
91:   min-height: 44px;
92:   padding: var(--rp-s3);
93:   background: var(--cp-inset);
94:   border: 1px solid var(--cp-rule);
95:   border-top: 4px solid var(--ax-band);
96:   border-radius: var(--cp-radius);
97: }
98: 
99: .ax-cell__glyph {
100:   color: var(--ax-band);
101:   font-size: 1.125rem;
102:   line-height: 1.2;
103: }
104: 
105: .ax-cell__label {
106:   font-family: var(--rp-font-utility);
107:   font-size: 0.6875rem;
108:   font-weight: 600;
109:   letter-spacing: 0.1em;
110:   text-transform: uppercase;
111:   color: var(--cp-ink-dim);
112: }
113: 
114: .ax-cell__count {
115:   grid-column: 1 / -1;
116:   font-family: var(--rp-font-display);
117:   font-weight: 700;
118:   font-size: 1.375rem;
119:   line-height: 1.1;
120:   font-variant-numeric: tabular-nums;
121:   color: var(--ax-band);
122: }
123: 
124: .ax-cell__percent {
125:   grid-column: 1 / -1;
126:   font-size: 0.75rem;
127:   font-variant-numeric: tabular-nums;
128:   color: var(--cp-ink-faint);
129: }
130: 
131: /* One mapping rule per band, scoped to the shell -------------------------- */
132: 
133: .ax-shell [data-band='critical'] {
134:   --ax-band: var(--cp-band-critical);
135: }
136: 
137: .ax-shell [data-band='storm_warning'] {
138:   --ax-band: var(--cp-band-storm);
139: }
140: 
141: .ax-shell [data-band='watch'] {
142:   --ax-band: var(--cp-band-watch);
143: }
144: 
145: .ax-shell [data-band='fair_skies'] {
146:   --ax-band: var(--cp-band-fair);
147: }
148: 
149: .ax-shell [data-band='clear'] {
150:   --ax-band: var(--cp-band-clear);
151: }
152: 
153: /* Strip plot -------------------------------------------------------------- */
154: 
155: .ax-figure {
156:   display: grid;
157:   gap: var(--rp-s2);
158:   margin: 0;
159:   min-width: 0;
160: }
161: 
162: .ax-plot__svg {
163:   display: block;
164:   width: 100%;
165:   height: auto;
166: }
167: 
168: .ax-seg {
169:   --ax-band: var(--cp-ink-faint);
170:   fill: var(--ax-band);
171:   opacity: 0.09;
172: }
173: 
174: .ax-bar {
175:   --ax-band: var(--cp-ink-faint);
176:   fill: var(--ax-band);
177:   opacity: 0.4;
178: }
179: 
180: .ax-dot {
181:   --ax-band: var(--cp-ink-faint);
182:   fill: var(--ax-band);
183:   opacity: 0.75;
184: }
185: 
186: .ax-axis {
187:   stroke: var(--cp-rule);
188:   stroke-width: 1;
189: }
190: 
191: .ax-tick,
192: .ax-unit {
193:   font-family: var(--rp-font-utility);
194:   font-size: 14px;
195:   fill: var(--cp-ink-faint);
196: }
197: 
198: .ax-unit {
199:   font-size: 13px;
200: }
201: 
202: .ax-ring {
203:   fill: none;
204:   stroke: var(--rp-paper);
205:   stroke-width: 1.5;
206: }
207: 
208: .ax-ring__label {
209:   font-family: var(--rp-font-utility);
210:   font-size: 13px;
211:   font-weight: 600;
212:   fill: var(--rp-paper);
213:   text-anchor: middle;
214: }
215: 
216: .ax-caption {
217:   font-family: var(--rp-font-body);
218:   font-size: 0.75rem;
219:   line-height: 1.5;
220:   color: var(--cp-ink-faint);
221: }
222: 
223: /* Loading and failure notes ------------------------------------------------ */
224: 
225: .ax-note {
226:   margin: 0;
227:   font-family: var(--rp-font-body);
228:   font-size: 0.875rem;
229:   line-height: 1.55;
230:   color: var(--cp-ink-dim);
231:   max-width: 60ch;
232: }

