1: @tailwind base;
2: @tailwind components;
3: @tailwind utilities;
4: 
5: html,
6: body,
7: #root {
8:   min-height: 100%;
9: }
10: 
11: body {
12:   @apply bg-void text-ink font-sans antialiased;
13: }
14: 
15: /* ==========================================================================
16:    Report tokens: financial print artifact meets mission control readout.
17:    Six named colors, three type roles, one spacing scale. No external fonts,
18:    so the booth machine never reaches the network.
19:    ========================================================================== */
20: 
21: :root {
22:   /* Palette (named hex values, the whole report runs on these six). */
23:   --rp-void: #070c18; /* archival navy ground */
24:   --rp-paper: #e9effa; /* cool paper ink */
25:   --rp-rule: #22314f; /* blueprint rule */
26:   --rp-verified: #35d0ae; /* provenance teal, locked and checked */
27:   --rp-money: #f4b740; /* ledger amber, discretionary dollars */
28:   --rp-stamp: #ff6a4d; /* audit stamp red, warnings and mismatches */
29: 
30:   /* Derived tones (alpha laid over the report ground). */
31:   --rp-panel: rgba(233, 239, 250, 0.04);
32:   --rp-panel-strong: rgba(233, 239, 250, 0.07);
33:   --rp-text-dim: rgba(233, 239, 250, 0.74);
34:   --rp-text-faint: rgba(233, 239, 250, 0.52);
35:   --rp-verified-dim: rgba(53, 208, 174, 0.45);
36:   --rp-verified-ghost: rgba(53, 208, 174, 0.1);
37:   --rp-money-dim: rgba(244, 183, 64, 0.5);
38:   --rp-money-ghost: rgba(244, 183, 64, 0.12);
39:   --rp-stamp-ghost: rgba(255, 106, 77, 0.14);
40:   --rp-gridline: rgba(34, 49, 79, 0.4);
41: 
42:   /* Type roles. Display and utility share one mono stack in two registers:
43:      heavy tight numerals for the readouts, tiny tracked caps for labels. */
44:   --rp-font-display: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
45:     "Liberation Mono", monospace;
46:   --rp-font-body: system-ui, -apple-system, "Segoe UI", Roboto,
47:     "Helvetica Neue", Arial, sans-serif;
48:   --rp-font-utility: var(--rp-font-display);
49: 
50:   /* Spacing scale. */
51:   --rp-s1: 0.25rem;
52:   --rp-s2: 0.5rem;
53:   --rp-s3: 0.75rem;
54:   --rp-s4: 1rem;
55:   --rp-s5: 1.5rem;
56:   --rp-s6: 2rem;
57:   --rp-s7: 3rem;
58:   --rp-s8: 4.5rem;
59: 
60:   --rp-radius: 4px;
61:   --rp-max: 72rem;
62: }
63: 
64: /* ==========================================================================
65:    Base: visible keyboard focus everywhere, smooth anchors, quiet motion.
66:    ========================================================================== */
67: 
68: :where(a, button, summary, [tabindex]):focus-visible {
69:   outline: 2px solid var(--rp-paper);
70:   outline-offset: 2px;
71:   box-shadow: 0 0 0 4px rgba(7, 12, 24, 0.85);
72: }
73: 
74: html {
75:   scroll-behavior: smooth;
76: }
77: 
78: ::selection {
79:   background: var(--rp-verified);
80:   color: var(--rp-void);
81: }
82: 
83: @media (prefers-reduced-motion: reduce) {
84:   html {
85:     scroll-behavior: auto;
86:   }
87: 
88:   *,
89:   *::before,
90:   *::after {
91:     animation-duration: 0.001ms !important;
92:     animation-iteration-count: 1 !important;
93:     transition-duration: 0.001ms !important;
94:   }
95: }
96: 
97: /* ==========================================================================
98:    Report shell
99:    ========================================================================== */
100: 
101: .rp-report {
102:   position: relative;
103:   color: var(--rp-paper);
104:   font-family: var(--rp-font-body);
105:   font-size: 1rem;
106:   line-height: 1.65;
107:   background-color: var(--rp-void);
108:   background-image:
109:     linear-gradient(var(--rp-gridline) 1px, transparent 1px),
110:     linear-gradient(90deg, var(--rp-gridline) 1px, transparent 1px);
111:   background-size: 28px 28px;
112:   background-position: center top;
113:   margin: calc(-1 * var(--rp-s6)) calc(-1 * var(--rp-s5)) calc(-1 * var(--rp-s6));
114:   padding: 0 var(--rp-s5) var(--rp-s8);
115:   border-top: var(--rp-rule-w) solid var(--rp-rule);
116: }
117: 
118: .rp-inner {
119:   max-width: var(--rp-max);
120:   margin: 0 auto;
121: }
122: 
123: .rp-eyebrow {
124:   font-family: var(--rp-font-utility);
125:   font-size: 0.6875rem;
126:   font-weight: 600;
127:   letter-spacing: 0.16em;
128:   text-transform: uppercase;
129:   color: var(--rp-text-faint);
130:   margin: 0;
131: }
132: 
133: .rp-section-title {
134:   font-family: var(--rp-font-display);
135:   font-weight: 700;
136:   font-size: clamp(1.35rem, 2.6vw, 1.85rem);
137:   letter-spacing: -0.02em;
138:   line-height: 1.15;
139:   margin: var(--rp-s2) 0 var(--rp-s4);
140: }
141: 
142: .rp-rule {
143:   border: 0;
144:   border-top: var(--rp-rule-w) solid var(--rp-rule);
145:   margin: var(--rp-s7) 0;
146: }
147: 
148: /* ==========================================================================
149:    Synthetic data banner: hazard tape, the loudest thing on the page.
150:    ========================================================================== */
151: 
152: .rp-banner {
153:   margin: var(--rp-s5) 0 var(--rp-s7);
154:   border: 2px solid var(--rp-void);
155:   border-radius: var(--rp-radius);
156:   overflow: hidden;
157:   background: repeating-linear-gradient(
158:     -45deg,
159:     var(--rp-money) 0 18px,
160:     var(--rp-void) 18px 36px
161:   );
162:   padding: 5px;
163: }
164: 
165: .rp-banner__body {
166:   background: var(--rp-money);
167:   color: var(--rp-void);
168:   padding: var(--rp-s4) var(--rp-s5);
169:   display: flex;
170:   flex-wrap: wrap;
171:   gap: var(--rp-s3) var(--rp-s5);
172:   align-items: baseline;
173:   justify-content: space-between;
174: }
175: 
176: .rp-banner__title {
177:   font-family: var(--rp-font-display);
178:   font-weight: 700;
179:   font-size: clamp(1rem, 2.4vw, 1.3rem);
180:   letter-spacing: 0.02em;
181:   text-transform: uppercase;
182:   margin: 0;
183: }
184: 
185: .rp-banner__text {
186:   margin: var(--rp-s1) 0 0;
187:   font-size: 0.9375rem;
188:   max-width: 62ch;
189: }
190: 
191: .rp-banner__seed {
192:   font-family: var(--rp-font-utility);
193:   font-size: 0.75rem;
194:   font-weight: 700;
195:   letter-spacing: 0.1em;
196:   text-transform: uppercase;
197:   white-space: nowrap;
198:   border: 2px solid var(--rp-void);
199:   border-radius: var(--rp-radius);
200:   padding: var(--rp-s1) var(--rp-s2);
201: }
202: 
203: /* ==========================================================================
204:    Hero: the thesis, then the five number readout strip
205:    ========================================================================== */
206: 
207: .rp-hero {
208:   padding-top: var(--rp-s5);
209: }
210: 
211: .rp-title {
212:   font-family: var(--rp-font-display);
213:   font-weight: 700;
214:   font-size: clamp(1.9rem, 4.6vw, 3.2rem);
215:   letter-spacing: -0.03em;
216:   line-height: 1.06;
217:   margin: var(--rp-s3) 0 var(--rp-s4);
218:   max-width: 24ch;
219: }
220: 
221: .rp-lede {
222:   font-size: clamp(1rem, 1.6vw, 1.1875rem);
223:   color: var(--rp-text-dim);
224:   max-width: 68ch;
225:   margin: 0;
