1574: /* ==========================================================================
1575:    Console tokens and surfaces (cp): the E2 instrument panel.
1576:    Reuses the rp palette as custom properties, adds one hue per verdict
1577:    band (mirrored in tailwind.config.js as text-cp-* utilities), and keeps
1578:    every interactive target at 44px or taller. Band text color comes from
1579:    the band's tailwind class, never from these rules, so the badge and the
1580:    forecast strip in E3 share one source of color.
1581:    ========================================================================== */
1582: 
1583: :root {
1584:   --cp-surface: var(--rp-panel);
1585:   --cp-surface-strong: var(--rp-panel-strong);
1586:   --cp-rule: var(--rp-rule);
1587:   --cp-ink: var(--rp-paper);
1588:   --cp-ink-dim: var(--rp-text-dim);
1589:   --cp-ink-faint: var(--rp-text-faint);
1590:   --cp-inset: rgba(7, 12, 24, 0.55);
1591: 
1592:   --cp-band-critical: #ff6a4d;
1593:   --cp-band-storm: #f4b740;
1594:   --cp-band-watch: #8b7cf6;
1595:   --cp-band-fair: #39c2e0;
