function renderTile(district, counts, onSelectDistrict) {
  const districtCounts = counts[String(district.district_id)] ?? null
  const severity = districtSeverity(district, districtCounts)
  const percent = districtSeverityPercent(district, districtCounts)
  const severe = districtCounts ? districtCounts.storm + districtCounts.flood : null  let binClass = ''
  let value = 'n/a'
  let aria = `District ${district.district_name}, no counts published for this scenario`
  if (district.no_data) {
    binClass = ' ax-tile--nodata'
    value = 'no data'
    aria = `District ${district.district_name}, no district data published`
  } else if (severity !== null && percent !== null && severe !== null) {
    binClass = ` ax-bin-${binFor(severity)}`
    value = `${percent}%`
    aria = `District ${district.district_name}, ${severe} of ${district.account_count} accounts in storm or flood`
  }
