export function regionsGrouped(doc: AtlasDoc): RegionGroup[] {
  const byRegion = new Map<string, DistrictRow[]>()
  for (const district of doc.districts) {
    const bucket = byRegion.get(district.region)
    if (bucket) bucket.push(district)
    else byRegion.set(district.region, [district])
  }
  return [...byRegion.entries()]
