const ROOT_KEYS = ['schema_version','generated_by','states','districts','account_district','baseline','scenarios']

export function parseAtlasDoc(raw: unknown): AtlasDoc {
  const root = asRecord(raw, 'atlas.json')
  requireExactKeys(root, ROOT_KEYS, 'atlas.json')

  const schemaVersion = asInteger(root.schema_version, 'atlas.json.schema_version')
  if (schemaVersion !== ATLAS_SCHEMA_VERSION) throw new Error(`atlas.json.schema_version must be ${ATLAS_SCHEMA_VERSION}, got ${schemaVersion}`)

  const generatedBy = asString(root.generated_by, 'atlas.json.generated_by')

  const states = asArray(root.states, 'atlas.json.states').map((state, index) => {
    const text = asString(state, `atlas.json.states[${index}]`)
    if (!(ATLAS_STATES as readonly string[]).includes(text)) throw new Error(`atlas.json.states[${index}] must be one of the canonical states, got "${text}"`)
    return text as AtlasState
  })
  if (states.join(',') !== ATLAS_STATES.join(',')) throw new Error(`atlas.json.states must be the canonical ladder ${ATLAS_STATES.join(', ')}, got ${states.join(', ')}`)

  const districts = asArray(root.districts, 'atlas.json.districts').map(parseDistrict)
  if (districts.length === 0) throw new Error('atlas.json.districts must hold at least one district')
  const districtIds = new Set<number>()
  for (const district of districts) {
    if (districtIds.has(district.district_id)) throw new Error(`atlas.json.districts must hold unique district_id values, got ${district.district_id} twice`)
    districtIds.add(district.district_id)
  }

  const accountDistrict = asRecord(root.account_district, 'atlas.json.account_district')
  for (const [key, value] of Object.entries(accountDistrict)) {
    const districtId = asInteger(value, `atlas.json.account_district["${key}"]`)
    if (!districtIds.has(districtId)) throw new Error(`atlas.json.account_district["${key}"] must reference a district_id from districts, got ${districtId}`)
  }

